import InputText from 'primevue/inputtext';
import Select from 'primevue/select';

export default {
    name: "Detail",
    data() {
      return {
        countries: [
          { name: 'Australia', code: 'AU' },
          { name: 'Brazil', code: 'BR' },
          { name: 'China', code: 'CN' },
          { name: 'Egypt', code: 'EG' },
          { name: 'France', code: 'FR' },
          { name: 'Germany', code: 'DE' },
          { name: 'India', code: 'IN' },
          { name: 'Japan', code: 'JP' },
          { name: 'Spain', code: 'ES' },
          { name: 'United States', code: 'US' }
        ]
      };
    },
    components: {
      InputText,
      Select
    }
  };
